using Marketplace.Domain.Common; namespace Marketplace.Domain.Inventory; public sealed class InventoryItem:AggregateRoot<long>{private InventoryItem(){}public long ProductId{get;private set;}public long ProductVariantId{get;private set;}public int StockQuantity{get;private set;}public int ReservedQuantity{get;private set;}public DateTime UpdatedAtUtc{get;private set;}public int AvailableQuantity=>StockQuantity-ReservedQuantity;public static InventoryItem Create(long id,long productId,long variantId,int stock){if(stock<0)throw new DomainException("Stock cannot be negative.");return new(){Id=id,ProductId=productId,ProductVariantId=variantId,StockQuantity=stock,UpdatedAtUtc=DateTime.UtcNow};}public void IncreaseStock(int q){if(q<=0)throw new DomainException("Quantity must be positive.");StockQuantity+=q;Touch();}public void DecreaseStock(int q){if(q<=0||q>AvailableQuantity)throw new DomainException("Insufficient stock.");StockQuantity-=q;Touch();}public void Reserve(int q){if(q<=0||q>AvailableQuantity)throw new DomainException("Insufficient stock.");ReservedQuantity+=q;Touch();}public void Release(int q){if(q<=0||q>ReservedQuantity)throw new DomainException("Invalid release.");ReservedQuantity-=q;Touch();}public void ConsumeReservation(int q){if(q<=0||q>ReservedQuantity||q>StockQuantity)throw new DomainException("Invalid consumption.");ReservedQuantity-=q;StockQuantity-=q;Touch();}private void Touch()=>UpdatedAtUtc=DateTime.UtcNow;}
